python - <<'PY'
import json,numpy as np
from PIL import Image
for k in ['live_005','live_006']:
 cam='robot0_agentview_right'; rgb=np.array(Image.open(f'/app/output/{k}/last/{cam}.jpg')); dep=np.load(f'/app/output/{k}/depth_{cam}.npy')[0]; m=json.load(open(f'/app/output/{k}/meta.json')); K=np.array(m['cameras'][cam]['intrinsic_cv']);M=np.array(m['cameras'][cam]['cam2world_gl'])
 def world(us,vs):
  z=dep[vs,us]; q=np.stack([(us-160)*z/K[0,0],-(vs-120)*z/K[1,1],-z,np.ones_like(z)],axis=0);return (M@q)[:3].T
 y,x=np.indices(dep.shape);blue=(rgb[:,:,2]>1.4*rgb[:,:,0])&(rgb[:,:,2]>1.15*rgb[:,:,1])&(x>160)&(x<220)&(y>120)&(y<205)
 yy,xx=np.where(blue); ws=world(xx,yy)
 print('\n',k,'blue count',len(xx))
 if len(xx):
  # split by v buckets
  for condname,cond in [('top', yy<160),('low',yy>=160)]:
   ids=np.where(cond)[0]
   if len(ids):print(condname,'pixels',np.round([xx[ids].mean(),yy[ids].mean()],1),'world',np.round(ws[ids].mean(0),3),'range',np.round(np.percentile(ws[ids],[5,95],axis=0),3))
 # can pixels manually near u198-212, v180-215 find values & depth
 for v in [180,185,190,195,200,205]:
  print('row',v,' '.join(f'{u}:{rgb[v,u].tolist()}d{dep[v,u]:.2f}' for u in range(190,216,5)))
PY

